"""Cross-family replication table: swarms generated by Gemini 3.8 Flash (swarm_S*G), detectors frozen (Gemma extractor).
Reads data/results_gemini.json (+ data/results.json for the Gemma-generated reference row) -> report/figs/crossfamily.tex"""
import json
from pathlib import Path
import numpy as np

ROOT = Path(__file__).resolve().parent.parent
G = json.load(open(ROOT / "data" / "results_gemini.json")); E = json.load(open(ROOT / "data" / "results.json"))
CONDS = ["S1", "S2", "S3", "S4", "S5"]
ROWS = [("D1 lexical", "D1 lexical"), ("D3 semantic", "D3 semantic"), ("D2 temporal (inv)", "D2 inverted"),
        ("D5 +context", "D5 LLM monitor +context"), ("A1 account-only", "A1 account-only"),
        ("D4c claim+provenance", "D4c +provenance"), ("D4 claim (ours)", r"\textbf{\ours{}}")]


def cell(R, keys, d):
    v = [R[k]["res"][d] for k in keys if k in R]
    return f"{np.mean([x['auroc'] for x in v]):.2f} / {np.mean([x['ap'] for x in v]):.2f}"


lines = []
for d, name in ROWS:
    lines.append(name + " & " + " & ".join(cell(G, [f"{c}G_s{s}" for s in range(3)], d) for c in CONDS) + r"\\")
lines.append(r"\midrule")
lines.append(r"\ours{}, Gemma-generated swarm & " + " & ".join(cell(E, [f"{c}_s{s}" for s in range(3)], "D4 claim (ours)") for c in CONDS) + r"\\")
(ROOT / "report" / "figs" / "crossfamily.tex").write_text("\n".join(lines) + "\n")
print("\n".join(lines))
